   $result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if(-not $result.complete -or -not $audit){throw 'Target restore is incomplete; preserve its result'};if(-not $controller.WaitForExit(15000) -or -not $agent.WaitForExit(60000) -or -not $station.WaitForExit(15000) -or $station.ExitCode -ne 0){throw 'Original controller exits unconfirmed'};$n=Get-VM -Id ([guid]$audit.platformId);if($n.State -ne 'Off'){throw 'Restored target must remain Off'};@{client=$result;attemptId=$attempt;prebootAudit=$audit;comparedCodeFiles=$compared;fixtureSha256=$expectedClient;controllerExited=$true;brokerExited=$true;stationExited=$true;restoredRetainedOff=$true}
  }
  foreach($name in @('result','audit-approved','progress')){$file=$name+'-'+$OperationId+'.json';Copy-Item -LiteralPath (Join-Path $case $file) -Destination (Join-Path $Directory ('target-'+$file)) -FromSession $session};Stop-VM -VM $vm -Confirm:$false;Save 'cross-host-complete-target-off' $outcome;exit 0
 }
}catch{Save 'failed' @{message=$_.Exception.Message;stack=$_.ScriptStackTrace;admission=@{targetState=$(if($vm){[string]$vm.State});startupBytes=$(if($mem){$mem.Startup});hostFreeBytes=$free;hostReserveBytes=$reserve;passed=$canStart}};throw}
finally{if($session){Remove-PSSession $session};if($labGuard){$labGuard.Dispose()};$caseGuard.Dispose()}
